{
  "type": "object",
  "properties": {
    "job_title": {
      "type": "string",
      "description": "The interview role or job title referenced in the subject or body, e.g. 'Java Developer', 'SAP FI Consultant'. Empty string when absent."
    },
    "name": {
      "type": "string",
      "description": "The sender's full name, taken from the From display name or the email signature. Empty string when absent."
    },
    "email": {
      "type": "string",
      "description": "The sender's own email address. Empty string when absent."
    },
    "phone": {
      "type": "string",
      "description": "Phone number from the body, signature or resume, in its original format including country code. Empty string when absent."
    },
    "mag_name": {
      "type": "string",
      "description": "The Risebird assessment group / skill panel this availability relates to — a technology or skill area such as 'Java', 'SAP FI', 'AWS DevOps', 'Android'. This is NOT a magazine, publication or project name. Risebird availability requests carry it in the subject line, usually after 'check for skills based on:' or 'check for'. Prefer the subject line. Empty string when absent."
    },
    "irf_id": {
      "type": "string",
      "description": "Any IRF id, skill channel id or reference code mentioned. Empty string when absent."
    },
    "has_login_credentials": {
      "type": "string",
      "enum": ["Yes", "No"],
      "description": "'Yes' when the email mentions login credentials, portal access or account details, otherwise 'No'."
    },
    "slots_per_day": {
      "type": "string",
      "description": "Number of interview slots the interviewer can take per day, e.g. '2'. Empty string when not stated."
    },
    "time_frame": {
      "type": "string",
      "description": "One or more of exactly these windows, comma separated: '6-10 AM', '10 AM-2 PM', '2-6 PM', '6-10 PM', '10 PM-12 AM'. Empty string when not stated."
    },
    "availability_intent": {
      "type": "string",
      "description": "What the interviewer actually says about their availability — dates, times, days of week or windows. MUST begin with the single word 'Available' when they confirm they can take interviews, or with 'Not available' when they decline or cannot. Follow that first word with the specifics. Empty string only when the email says nothing at all about availability."
    },
    "mail_body_intent": {
      "type": "string",
      "description": "One-line summary of the email's purpose, e.g. 'Sharing availability for next week', 'Requesting a slot change', 'Declining for this cycle'."
    },
    "concerns_or_not_interested": {
      "type": "string",
      "description": "Any hesitation, condition, concern or expression of disinterest. Use exactly 'None' when there is none."
    },
    "resume_fitment": {
      "type": "string",
      "enum": ["Strong Fit", "Moderate Fit", "Weak Fit", "N/A"],
      "description": "Fitment of the attached resume text against the job title. Use 'N/A' when no resume text is supplied."
    }
  },
  "required": [
    "name",
    "mag_name",
    "availability_intent",
    "mail_body_intent",
    "concerns_or_not_interested",
    "resume_fitment"
  ]
}

parameters.jsCode:
// Flatten the extractor output into the flat record the Risebird webhook expects.
// The Information Extractor returns its result under `output`, schema-validated, so there
// is no response envelope to reverse-engineer here — that guesswork is what silently
// turned every field into 'N/A' when the shape did not match.
const FIELDS = [
  'job_title',
  'name',
  'email',
  'phone',
  'mag_name',
  'irf_id',
  'has_login_credentials',
  'slots_per_day',
  'time_frame',
  'availability_intent',
  'mail_body_intent',
  'concerns_or_not_interested',
  'resume_fitment'
];

function text(value) {
  return value === undefined || value === null ? '' : String(value).trim();
}

// Risebird's outbound availability mails label both values explicitly, and the reply keeps
// the subject behind a 'Re:':
//   'Risebird - Interviewers Availability Check -MagName : {MAG} - IRFID : {IRF}- ...'
// Older campaigns instead use:
//   'Current Availability (2 days) check for skills based on: {MAG} Risebird Interviews'
//   'Current Availability (2 days) check for {role} Risebird Interviews'
// Reading the label beats asking the model, and mag_name is what resolves the assessment
// group that auto-close depends on. Both shapes also appear in the body, which is the
// fallback when the subject has been trimmed by the sender's client.
function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function firstMatch(haystack, patterns, maxLength) {
  for (const pattern of patterns) {
    const match = haystack.match(pattern);
    const value = match ? match[1].trim().replace(/^[-:,\s]+|[-:,\s]+$/g, '').trim() : '';
    if (value && value.length <= maxLength) return value;
  }
  return '';
}

function magFrom(text) {
  return firstMatch(clean(text), [
    /mag\s*name\s*:\s*(.+?)\s*[-–—]\s*IRF\s*ID\s*:/i,
    /mag\s*name\s*:\s*(.+?)(?:\s+[-–—]\s+|$)/i,
    /check\s+for\s+skills\s+based\s+on\s*:\s*(.+?)\s*Risebird\s+Interviews/i,
    /check\s+for\s+(.+?)\s*Risebird\s+Interviews/i
  ], 120);
}

// The IRF id is a 10-character alphanumeric code, e.g. SYNEPYTPY8.
function irfFrom(text) {
  return firstMatch(clean(text), [/IRF\s*ID\s*:?\s*([A-Za-z0-9]{6,14})\b/i], 14);
}

const contexts = $('Build AI Input').all();
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const context = (contexts[i] && contexts[i].json) || {};
  const itemJson = (items[i] && items[i].json) || {};
  const extracted = itemJson.output && typeof itemJson.output === 'object' ? itemJson.output : {};

  // On a failed extraction the node passes the input item straight through
  // (onError: continueRegularOutput), so none of the schema fields are present. Say so
  // explicitly instead of emitting a full row of 'N/A' that reads like a real result.
  const parseFailed = !FIELDS.some((field) =>
    Object.prototype.hasOwnProperty.call(extracted, field));

  const record = {};
  for (const field of FIELDS) {
    record[field] = text(extracted[field]) || 'N/A';
  }
  if (record.concerns_or_not_interested === 'N/A') record.concerns_or_not_interested = 'None';
  if (!context.resume_text) record.resume_fitment = 'N/A';

  // The labelled subject beats the model, then the labelled body, then the model.
  record.mag_name = magFrom(context.subject) || magFrom(context.body) || record.mag_name;
  record.irf_id = irfFrom(context.subject) || irfFrom(context.body) || record.irf_id;

  // A one-word reply like "Interested" names no role, so the model rightly returns nothing.
  // The MAG is the skill the campaign went out for, which is what the Job Title column is
  // there to show — without this the column reads 'N/A' on exactly the replies that matter.
  if (record.job_title === 'N/A' && record.mag_name !== 'N/A') {
    record.job_title = record.mag_name;
  }

  // The Gmail From header is authoritative; the model's guess is only a fallback.
  const modelEmail = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(record.email) ? record.email.toLowerCase() : '';
  record.sender_email = context.from_email || modelEmail;
  record.email = record.sender_email;

  record.message_id = context.message_id || '';
  record.subject = context.subject || '';
  record.mail_content = context.body || '';
  record.received_at = context.received_at || new Date().toISOString();
  record.attachment_count = Number(context.attachment_count || 0);
  record.ai_parse_failed = parseFailed;

  out.push({ json: record });
}

return out;

// One item per attachment, pulled back off the trigger by message id so that a poll
// carrying several emails never mixes one interviewer's resume into another's row.
const triggerByMessageId = new Map();
for (const item of $('Gmail Trigger').all()) {
  triggerByMessageId.set(String((item.json || {}).id || ''), item);
}

const out = [];

for (const item of $input.all()) {
  const messageId = String((item.json || {}).message_id || '');
  const trigger = triggerByMessageId.get(messageId);
  const binary = (trigger && trigger.binary) || {};

  for (const key of Object.keys(binary)) {
    if (!key.startsWith('attachment_')) continue;
    const file = binary[key];
    out.push({
      json: { message_id: messageId, fileName: file.fileName || key },
      binary: { data: file }
    });
  }
}

return out;

// Collapse the per-attachment uploads back to one item per email. Relay wrote a single
// row using the first uploaded file, so the first link wins here too.
const uploads = $input.all();
const sources = $('Split Attachments').all();

const linksByMessageId = new Map();

for (let i = 0; i < uploads.length; i++) {
  const file = (uploads[i] && uploads[i].json) || {};
  const messageId = String(((sources[i] || {}).json || {}).message_id || '');
  const link = file.webViewLink || (file.id ? `https://drive.google.com/file/d/${file.id}/view` : '');
  if (!link) continue;
  if (!linksByMessageId.has(messageId)) linksByMessageId.set(messageId, []);
  linksByMessageId.get(messageId).push(link);
}

const out = [];

for (const item of $('Parse AI').all()) {
  const record = { ...((item.json) || {}) };

  // Mirrors the IF condition, so an email is never dropped just because Drive
  // returned no usable link for it.
  if (Number(record.attachment_count || 0) === 0) continue;

  const links = linksByMessageId.get(String(record.message_id || '')) || [];
  record.resume_link = links[0] || 'None';
  record.resume_links = links.join(', ');
  out.push({ json: record });
}

return out;

// Single convergence point for both branches, so the sheet row and the webhook payload
// are always built from one identical record.
const out = [];

for (const item of $input.all()) {
  const record = { ...((item.json) || {}) };

  record.resume_link = String(record.resume_link || '').trim() || 'None';
  record.has_attachment = Number(record.attachment_count || 0) > 0;
  record.source = 'n8n';

  out.push({ json: record });
}

return out;
